export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const dt = 0.01;
  const g = 9.81;
  const drag = 0.42;

  let initialized = false;
  let px = 0, py = 0.07, pz = 0;
  let vx = 0, vy = 0, vz = 0;
  let dx = 0, dy = 0, dz = 0;
  let massEst = 0.73;
  let uMotor = 0.45;
  let lastThrust = 0.45;

  let expRoll = 0, expPitch = 0;
  let expRollRate = 0, expPitchRate = 0;
  let intRoll = 0, intPitch = 0;
  let biasRoll = 0, biasPitch = 0;
  let yawInt = 0;

  let gateIdx = 0;
  let holdX = null;

  return {
    step(obs) {
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;

      if (!initialized) {
        initialized = true;
        px = p.x; py = p.y; pz = p.z;
        vx = v.x; vy = v.y; vz = v.z;
        expRoll = att.roll; expPitch = att.pitch;
      }

      // Update motor lag model (mean lag ~ 0.04s)
      uMotor += (lastThrust - uMotor) * (1 - Math.exp(-dt / 0.04));

      // Thrust direction from measured attitude
      const cr = Math.cos(att.roll), sr = Math.sin(att.roll);
      const cp = Math.cos(att.pitch), sp = Math.sin(att.pitch);
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const bodyX = sp * cr, bodyZ = -sr;
      const dirX = cy * bodyX + sy * bodyZ;
      const dirY = cp * cr;
      const dirZ = -sy * bodyX + cy * bodyZ;

      const airborne = p.y > 0.085;
      const aTot = (16 * uMotor) / massEst;

      // Model accelerations using measured attitude
      const ux = aTot * dirX - (drag / massEst) * vx;
      const uy = aTot * dirY - (drag / massEst) * vy - g;
      const uz = aTot * dirZ - (drag / massEst) * vz;

      // State & disturbance observer predictor-corrector
      const pxPred = px + vx * dt + 0.5 * (ux + dx) * dt * dt;
      const vxPred = vx + (ux + dx) * dt;
      const pyPred = py + vy * dt + 0.5 * (uy + dy) * dt * dt;
      const vyPred = vy + (uy + dy) * dt;
      const pzPred = pz + vz * dt + 0.5 * (uz + dz) * dt * dt;
      const vzPred = vz + (uz + dz) * dt;

      const epX = p.x - pxPred, evX = v.x - vxPred;
      const epY = p.y - pyPred, evY = v.y - vyPred;
      const epZ = p.z - pzPred, evZ = v.z - vzPred;

      px = pxPred + 0.65 * epX;
      vx = vxPred + 0.38 * evX + 8.0 * epX;
      py = pyPred + 0.65 * epY;
      vy = vyPred + 0.38 * evY + 8.0 * epY;
      pz = pzPred + 0.65 * epZ;
      vz = vzPred + 0.38 * evZ + 8.0 * epZ;

      if (airborne) {
        dx = clamp(dx + 22.0 * evX + 90.0 * epX, -4.5, 4.5);
        dz = clamp(dz + 22.0 * evZ + 90.0 * epZ, -4.5, 4.5);
        dy = clamp(dy + 12.0 * evY + 40.0 * epY, -2.5, 2.5);

        // Adapt effective mass from vertical disturbance dy
        // Since true vertical wind is 0, dy is due to mass mismatch
        if (dirY > 0.7 && uMotor > 0.25) {
          massEst = clamp(massEst - 0.08 * dy * dt, 0.58, 0.94);
          dy *= 0.92;
        }
      } else {
        dx *= 0.95;
        dy *= 0.95;
        dz *= 0.95;
      }

      if (obs.gateIndex !== gateIdx) {
        gateIdx = obs.gateIndex;
        holdX = null;
      }

      let tx, ty, tz;
      let vxRef = 0, vyRef = 0, vzRef = 0;
      let kpX = 5.0, kdX = 3.8;
      let kpY = 6.5, kdY = 4.2;
      let kpZ = 6.5, kdZ = 4.4;
      let maxTilt = 0.48;
      let landingTouchdown = false;

      if (obs.gateIndex < 3) {
        const gC = obs.nextGate.centre;
        ty = gC.y;
        tz = gC.z;

        const distY = Math.abs(py - gC.y);
        const distZ = Math.abs(pz - gC.z);
        const dtCross = clamp((gC.x - px) / Math.max(0.35, vx), 0.0, 0.28);
        const predY = py + vy * dtCross;
        const predZ = pz + vz * dtCross;
        const errY = Math.max(distY, Math.abs(predY - gC.y));
        const errZ = Math.max(distZ, Math.abs(predZ - gC.z));

        // Before reaching the gate corridor, approach x = gC.x - 0.32 while converging y and z
        const alignedEnough = errZ < 0.062 && errY < 0.11 && Math.abs(vz) < 0.28 && Math.abs(vy) < 0.35;
        const farEnough = px < gC.x - 0.38;

        if (farEnough && (distZ > 0.18 || distY > 0.25)) {
          // Approach staging point in front of gate
          tx = gC.x - 0.32;
          vxRef = clamp((tx - px) * 1.8, -0.6, 0.85);
          holdX = null;
        } else if (!alignedEnough && px < gC.x - 0.03) {
          // Hold x safely in front of the gate plane until y and z are inside the safe inner core
          if (holdX === null) {
            holdX = Math.min(px, gC.x - 0.18);
          } else {
            holdX = Math.min(holdX, gC.x - 0.18);
          }
          tx = Math.max(gC.x - 0.35, holdX);
          vxRef = 0;
          kpZ = 8.0; kdZ = 5.0;
          kpY = 7.5; kdY = 4.6;
        } else {
          // Aligned: fly cleanly through the gate center
          holdX = null;
          tx = gC.x + 0.35;
          vxRef = 0.75;
          kpZ = 8.5; kdZ = 5.2;
          kpY = 7.5; kdY = 4.6;
        }
      } else {
        // Landing phase on pad (2.05, 0, 1.65)
        const pad = obs.pad.centre;
        tx = pad.x;
        tz = pad.z;
        const distXZ = Math.hypot(px - pad.x, pz - pad.z);
        const speedXZ = Math.hypot(vx, vz);

        kpX = 5.8; kdX = 4.2;
        kpZ = 5.8; kdZ = 4.2;

        if (distXZ > 0.25) {
          // Glide down smoothly toward pad
          ty = clamp(0.28 + 0.65 * (distXZ - 0.25), 0.28, 1.05);
        } else if (distXZ > 0.095 || speedXZ > 0.28) {
          // Settle horizontally at low hover over pad
          ty = 0.22;
        } else {
          // Descend softly onto pad
          ty = 0.055;
          if (py > 0.13) {
            vyRef = -0.38;
          } else {
            vyRef = -0.15;
          }
          if (py <= 0.11) {
            maxTilt = 0.14;
          }
          if (py <= 0.088 && distXZ <= 0.115 && Math.hypot(vx, vy, vz) < 0.42) {
            landingTouchdown = true;
          }
        }
      }

      const axDes = clamp(kpX * (tx - px) + kdX * (vxRef - vx), -3.6, 3.6);
      const ayDes = clamp(kpY * (ty - py) + kdY * (vyRef - vy), -3.5, 4.5);
      const azDes = clamp(kpZ * (tz - pz) + kdZ * (vzRef - vz), -3.6, 3.6);

      // Desired thrust acceleration vector (compensating drag and estimated wind disturbance)
      const axThrust = axDes + (drag / massEst) * vx - dx;
      const ayThrust = Math.max(1.5, ayDes + g + (drag / massEst) * vy - dy);
      const azThrust = azDes + (drag / massEst) * vz - dz;

      // Nonlinear exact attitude inversion
      const abx = cy * axThrust - sy * azThrust;
      const abz = sy * axThrust + cy * azThrust;

      const pitchDes = clamp(Math.atan2(abx, ayThrust), -maxTilt, maxTilt);
      const rollDes = clamp(-Math.atan2(abz, Math.hypot(abx, ayThrust)), -maxTilt, maxTilt);

      // Expected healthy attitude tracker to isolate weak-motor attitude offset
      if (airborne) {
        const errR = expRoll - att.roll;
        const errP = expPitch - att.pitch;
        biasRoll = clamp(biasRoll + 1.8 * errR * dt, -0.22, 0.22);
        biasPitch = clamp(biasPitch + 1.8 * errP * dt, -0.22, 0.22);
      }

      // Lead-compensated attitude command
      let rollCmd = clamp(rollDes + 0.75 * (rollDes - att.roll) - 0.07 * rates.roll + biasRoll, -maxTilt, maxTilt);
      let pitchCmd = clamp(pitchDes + 0.75 * (pitchDes - att.pitch) - 0.07 * rates.pitch + biasPitch, -maxTilt, maxTilt);

      let thrustCmd = clamp((massEst * ayThrust) / (16 * Math.max(0.55, dirY)), 0, 1);

      if (landingTouchdown) {
        thrustCmd = 0.05;
        rollCmd = clamp(rollDes, -0.12, 0.12);
        pitchCmd = clamp(pitchDes, -0.12, 0.12);
      }

      // Update expected healthy inner loop attitude for next step
      for (let sub = 0; sub < 2; sub++) {
        const subDt = 0.005;
        const er = rollCmd - expRoll;
        const ep = pitchCmd - expPitch;
        intRoll = clamp(intRoll + er * subDt, -0.35, 0.35);
        intPitch = clamp(intPitch + ep * subDt, -0.35, 0.35);
        const ar = 65 * er - 13.4 * expRollRate + 22 * intRoll;
        const ap = 65 * ep - 13.4 * expPitchRate + 22 * intPitch;
        expRollRate += ar * subDt;
        expPitchRate += ap * subDt;
        expRoll += expRollRate * subDt;
        expPitch += expPitchRate * subDt;
      }

      if (airborne) {
        yawInt = clamp(yawInt - att.yaw * dt, -0.5, 0.5);
      }
      const yawRate = clamp(-4.0 * att.yaw - 0.25 * rates.yaw + 2.5 * yawInt, -2, 2);

      lastThrust = thrustCmd;
      return { thrust: thrustCmd, roll: rollCmd, pitch: pitchCmd, yawRate };
    },
  };
}

