      const vxPred = vx + (ux + dx) * dt;
      const pyPred = py + vy * dt + 0.5 * (uy + dy) * dt * dt;
      const vyPred = vy + (uy + dy) * dt;
      const pzPred = pz + vz * dt + 0.5 * (uz + dz) * dt * dt;
      const vzPred = vz + (uz + dz) * dt;

