        pitchCmd = clamp(pitchDes, -0.12, 0.12);
      }

      // Update expected healthy inner loop attitude for next step
      for (let sub = 0; sub < 2; sub++) {
        const subDt = 0.005;
        const er = rollCmd - expRoll;
        const ep = pitchCmd - expPitch;
        intRoll = clamp(intRoll + er * subDt, -0.35, 0.35);
        intPitch = clamp(intPitch + ep * subDt, -0.35, 0.35);
        const ar = 65 * er - 13.4 * expRollRate + 22 * intRoll;
        const ap = 65 * ep - 13.4 * expPitchRate + 22 * intPitch;
        expRollRate += ar * subDt;
        expPitchRate += ap * subDt;
        expRoll += expRollRate * subDt;
        expPitch += expPitchRate * subDt;
      }

