        yawInt = clamp(yawInt - att.yaw * dt, -0.5, 0.5);
      }
      const yawRate = clamp(-4.0 * att.yaw - 0.25 * rates.yaw + 2.5 * yawInt, -2, 2);

      lastThrust = thrustCmd;
      return { thrust: thrustCmd, roll: rollCmd, pitch: pitchCmd, yawRate };
    },
  };
}
